UPDATE ITEM 
SET SAFETY_AMOUNT = CASE 

        WHEN ITEM_NO = #{itemVO.itemNo} THEN #{itemVO.safetyAmount}

END
WHERE ITEM_NO IN 

    #{itemVO.itemNo}

UPDATE INVNTRY_RECORD B 
SET    B.REMAIN_AMOUNT = (
    SELECT A.RECORD_AMOUNT
    FROM  INVNTRY_RECORD A
    WHERE A.ITEM_NO = #{itemNo}
    AND   A.RECORD_TY = 1
    AND   A.INVNTRY_RECORD_NO = B.INVNTRY_RECORD_NO
)
WHERE B.ITEM_NO = #{itemNo}
AND   B.RECORD_TY = 1
